// Derive activeEntityUpdate DETERMINISTICALLY from real tool data (not LLM text).
const out = $json.output || '';
const steps = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
const usedTools = [];
let active = null;
const parse = (o) => { try { return typeof o === 'string' ? JSON.parse(o) : o; } catch (e) { return null; } };
const one = (a) => (Array.isArray(a) && a.length === 1) ? a[0] : null;
const ENT = { clients:'client', opportunities:'opportunity', service_cases:'service_case', tasks:'task', calendar_events:'calendar_event', properties:'property', documents:'document', activities:'activity' };
for (const st of steps) {
  const tool = st && st.action && st.action.tool;
  const ti = (st && st.action && st.action.toolInput) || {};
  if (tool && usedTools.indexOf(tool) < 0) usedTools.push(tool);
  const obs = parse(st && st.observation);
  if (!obs || obs.ok === false) continue;
  const res = obs.result || {};
  let cand = null;
  if (tool === 'get_client_360' || tool === 'get_latest_client') { const c = res.client; if (c && c.id && c.name) cand = { type:'client', id:c.id, label:c.name }; }
  else if (tool === 'search_clients') { const c = one(res.results || res.clients || res.rows); if (c && c.id && c.name) cand = { type:'client', id:c.id, label:c.name }; }
  else if (tool === 'search_properties') { const p = one(res.results || res.rows); if (p && p.id) cand = { type:'property', id:p.id, label: p.title || p.address || 'Propiedad' }; }
  else if (tool === 'get_documents_metadata') { const d = one(res.results || res.documents || res.rows); if (d && d.id) cand = { type:'document', id:d.id, label: d.title || 'Documento' }; }
  else if (tool === 'crm_read_query') { const row = one(res.rows || res.results); const ent = ENT[res.entity]; if (row && row.id && ent) cand = { type:ent, id:row.id, label: row.name || row.title || row.address || ent }; }
  else if (tool === 'get_client_opportunities' || tool === 'get_client_service_cases') { if (ti.clientId) cand = { type:'client', id: ti.clientId }; }
  if (cand) active = cand;
}
const activeEntityUpdate = active ? { type:active.type, id:active.id, label: active.label || null, source:'tool', confidence: active.label ? 'high' : 'medium' } : null;
return { reply: out, activeEntityUpdate, usedTools, limitations: [], error: null };

